function run(runFn, sources, options) {
  if (sources.length === 0)
    runRepl(runFn, options)
  else
    runFiles(runFn, sources, options)
}
    // ...
function runFiles(runFn, files, options) {
  for (const file of files) {
    if (file === '-')
      runRepl(runFn, options)
    else {
      const code = readFileSync(file).toString()
      runFn(code, options)
    }
  }
}

